class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])

        # dp[i][j][k] = max profit to reach cell (i, j) with k neutralizations used
        # We'll use a 2D array for each state of k neutralizations used.
        # Since we only need the previous row, we can optimize space, but given constraints (m, n <= 500),
        # a full 3D DP table of size 500x500x3 is acceptable (approx 750KB).

        # Initialize dp table with dimensions [m][n][3]
        # Use a large negative number for unreachable states initially
        NEG_INF = float('-inf')
        dp = [[[NEG_INF for _ in range(3)] for _ in range(n)] for _ in range(m)]

        # Base case: starting at (0, 0)
        val = coins[0][0]
        if val >= 0:
            dp[0][0][0] = val
        else:
            # If the start has a robber, we have options:
            # - Don't neutralize: profit = val (negative)
            # - Neutralize: profit = 0
            dp[0][0][0] = val
            dp[0][0][1] = 0

        # Fill DP table
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                # Try moving from top (i-1, j)
                if i > 0:
                    for k in range(3):
                        prev_val = dp[i-1][j][k]
                        if prev_val != NEG_INF:
                            current_val = prev_val + coins[i][j]

                            # If current cell has a robber and we don't have enough neutralizations left to cover it,
                            # we still take the value (it's just lower). The problem says we CAN neutralize up to 2 cells.
                            # So we just add the value. If it's negative, it reduces our total.
                            # But we also need to consider using a neutralization here if available.

                            # Option 1: Don't use neutralization at this cell
                            if current_val > dp[i][j][k]:
                                dp[i][j][k] = current_val

                            # Option 2: Use a neutralization at this cell (only if k < 2)
                            if k < 2:
                                new_k = k + 1
                                prev_val_neu = dp[i-1][j][new_k]
                                if prev_val_neu != NEG_INF:
                                    # If we neutralize, we gain 0 from this cell (regardless of sign)
                                    val_neu = prev_val_neu
                                    if val_neu > dp[i][j][new_k]:
                                        dp[i][j][new_k] = val_neu

                                # Also, we could have come from a state where we already used a neutralization earlier
                                # and now we are not using one at this cell? That's covered by the first option above.

                # Try moving from left (i, j-1)
                if j > 0:
                    for k in range(3):
                        prev_val = dp[i][j-1][k]
                        if prev_val != NEG_INF:
                            current_val = prev_val + coins[i][j]

                            if current_val > dp[i][j][k]:
                                dp[i][j][k] = current_val

                            if k < 2:
                                new_k = k + 1
                                prev_val_neu = dp[i][j-1][new_k]
                                if prev_val_neu != NEG_INF:
                                    val_neu = prev_val_neu
                                    if val_neu > dp[i][j][new_k]:
                                        dp[i][j][new_k] = val_neu

        # The answer is the maximum over all possible neutralization counts at (m-1, n-1)
        return max(dp[m-1][n-1])

