class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Group edges by weight to facilitate binary search
        weight_groups = {}
        for u, v, w in edges:
            if w not in weight_groups:
                weight_groups[w] = []
            weight_groups[w].append((u, v))

        # Determine the maximum weight present in the edges
        max_w = 0
        if edges:
            max_w = max(e[2] for e in edges)

        # Binary search for the minimum possible maximum edge weight
        low = 0
        high = max_w
        res = -1

        # Feasibility check function for a given max weight w
        def feasible(w):
            # Build the reverse graph with edges having weight <= w
            # In the reverse graph, an edge v -> u corresponds to an original edge u -> v
            adj = [[] for _ in range(n)]
            for key in weight_groups:
                if key > w:
                    continue
                for u, v in weight_groups[key]:
                    adj[v].append(u)  # reverse edge: v -> u

            # BFS from node 0 in the reverse graph
            # We track the number of incoming edges for each node in the reverse graph (which corresponds to outgoing edges in the original graph)
            in_degree = [0] * n
            visited = [False] * n
            visited[0] = True
            queue = collections.deque([0])

            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if not visited[v]:
                        # Only add edge if the node hasn't exceeded the threshold outgoing edges (incoming in reverse)
                        if in_degree[v] < threshold:
                            in_degree[v] += 1
                            visited[v] = True
                            queue.append(v)

            # Check if all nodes are reachable from 0 in the reverse graph
            return all(visited)

        # Binary search to find the minimum max weight
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                res = mid
                high = mid - 1
            else:
                low = mid + 1

        return res

