class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Function to get all elements in a diagonal (bottom-left triangle)
        def get_bottom_left_diag(i):
            diag = []
            for j in range(n):
                if i + j < n:
                    diag.append(grid[i][j])
            return diag

        # Function to get all elements in a diagonal (top-right triangle)
        def get_top_right_diag(j):
            diag = []
            for i in range(n):
                if i + j < n:
                    diag.append(grid[i][j])
            return diag

        # Process bottom-left triangle diagonals (including the middle diagonal)
        # These are diagonals starting from row 0 to n-1 with column 0
        for i in range(n):
            diag = get_bottom_left_diag(i)
            if len(diag) > 1:
                diag.sort(reverse=True)
                # Put back into the matrix
                idx = 0
                for j in range(n):
                    if i + j < n:
                        grid[i][j] = diag[idx]
                        idx += 1

        # Process top-right triangle diagonals
        # These are diagonals starting from row 0 to n-1 with column n-1 down to 0
        for j in range(n - 1, -1, -1):
            diag = get_top_right_diag(j)
            if len(diag) > 1:
                diag.sort()
                # Put back into the matrix
                idx = 0
                for i in range(n):
                    if i + j < n:
                        grid[i][j] = diag[idx]
                        idx += 1

        return grid

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Iterate through all possible substrings of length k
        for i in range(n - k + 1):
            substring = s[i:i+k]

            # Check if the substring consists of only one distinct character
            if len(set(substring)) != 1:
                continue

            char_in_sub = substring[0]

            # Check boundary conditions
            before_ok = True
            after_ok = True

            # Check character before the substring
            if i > 0:
                if s[i-1] == char_in_sub:
                    before_ok = False

            # Check character after the substring
            if i + k < n:
                if s[i+k] == char_in_sub:
                    after_ok = False

            # If both neighbors are different (or don't exist), return True
            if before_ok and after_ok:
                return True

        return False

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def min_cost(char1, char2):
            a = ord(char1) - ord('a')
            b = ord(char2) - ord('a')
            diff = abs(a - b)
            return min(diff, 26 - diff)

        # dp[i][j] will be a dictionary: length -> min_cost
        dp = [[{} for _ in range(n)] for _ in range(n)]

        # Base case: single characters
        for i in range(n):
            dp[i][i] = {1: 0}

        # Iterate over lengths from 2 to n
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                candidates = {}

                # Option 1: skip s[i] -> take from dp[i+1][j]
                if i + 1 <= j:
                    for l, c in dp[i+1][j].items():
                        if c < candidates.get(l, float('inf')):
                            candidates[l] = c

                # Option 2: skip s[j] -> take from dp[i][j-1]
                if i <= j - 1:
                    for l, c in dp[i][j-1].items():
                        if c < candidates.get(l, float('inf')):
                            candidates[l] = c

                # Option 3: use s[i] and s[j]
                if i + 1 > j - 1:
                    # inner part is empty
                    c_val = min_cost(s[i], s[j])
                    if c_val <= k:
                        if 2 not in candidates or c_val < candidates[2]:
                            candidates[2] = c_val
                else:
                    c_val = min_cost(s[i], s[j])
                    if c_val <= k:
                        for l, c in dp[i+1][j-1].items():
                            new_l = l + 2
                            new_c = c + c_val
                            if new_c <= k:
                                if new_l not in candidates or new_c < candidates[new_l]:
                                    candidates[new_l] = new_c

                dp[i][j] = candidates

        # Find the maximum length in dp[0][n-1] with cost <= k
        ans = 0
        for l, c in dp[0][n-1].items():
            if c <= k:
                ans = max(ans, l)
        return ans

