class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # Create a copy of nums to simulate the state after each query
        current_nums = nums[:]

        # Process each query in sequence
        for k in range(len(queries)):
            l, r, val = queries[k]

            # Decrement values in the range [l, r]
            for i in range(l, r + 1):
                current_nums[i] -= val
                # If any element becomes negative, it's impossible to make the array all zeros
                # because we only perform decrements and cannot reverse them.
                if current_nums[i] < 0:
                    return -1

            # Check if the array has become a Zero Array
            if all(x == 0 for x in current_nums):
                return k + 1

        # If we process all queries and the array is still not zero
        return -1

class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        # Calculate the total number of cells on the n x n deck
        total_cells = n * n

        # Calculate the maximum number of containers allowed by weight limit
        # This is floor(maxWeight / w)
        weight_limited_count = maxWeight // w

        # The actual number of containers is the minimum of the two limits
        return min(total_cells, weight_limited_count)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        # Build the graph using an adjacency list
        adj = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct integers common to both properties[i] and properties[j]
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection_len = len(set_i & set_j)

                if intersection_len >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Initialize visited array and connected components counter
        visited = [False] * n
        components = 0

        # Iterate over all nodes and perform DFS/BFS for each unvisited node
        for i in range(n):
            if not visited[i]:
                components += 1
                stack = [i]
                visited[i] = True

                while stack:
                    curr = stack.pop()
                    for neighbor in adj[curr]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)

        return components

class Solution:
    def maxAdjacentDistance(self, nums: List[int]) -> int:
        n = len(nums)
        max_diff = 0

        # Check all adjacent pairs including the wrap-around pair (last and first)
        for i in range(n):
            # Current element and next element (with circular wrap-around)
            diff = abs(nums[(i + 1) % n] - nums[i])
            max_diff = max(max_diff, diff)

        return max_diff

