class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            # Determine the boundaries for comparison
            left_idx = i - k
            right_idx = i + k

            # Check if left index exists and get value if it does
            left_val = None
            if left_idx >= 0:
                left_val = nums[left_idx]

            # Check if right index exists and get value if it does
            right_val = None
            if right_idx < n:
                right_val = nums[right_idx]

            # Determine the threshold for 'strictly greater'
            # If both indices exist, must be > max(left_val, right_val)
            # If only one exists, must be > that value
            # If neither exists, condition is always true (no constraints)

            is_good = True

            if left_val is not None or right_val is not None:
                # There is at least one neighbor to compare against
                if left_val is not None and right_val is not None:
                    threshold = max(left_val, right_val)
                elif left_val is not None:
                    threshold = left_val
                else:
                    threshold = right_val

                if nums[i] <= threshold:
                    is_good = False

            if is_good:
                total_sum += nums[i]

        return total_sum

class Solution:
    def reverseDegree(self, s: str) -> int:
        # Map each character to its reversed alphabet index: 'a'->26, 'b'->25, ..., 'z'->1
        char_to_val = {chr(ord('a') + i): 27 - i for i in range(26)}

        total = 0
        for idx, char in enumerate(s, start=1):  # 1-indexed position
            total += char_to_val[char] * idx

        return total
